import sys
import random

class RandomizedSetBrute:
    def __init__(self):
        self.lst = []
    def insert(self, val):
        if val in self.lst:
            return False
        self.lst.append(val)
        return True
    def remove(self, val):
        if val not in self.lst:
            return False
        self.lst.remove(val)
        return True
    def getRandom(self):
        return random.choice(self.lst)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    q = int(data[0])
    rs = RandomizedSetBrute()
    i = 1
    while q > 0 and i < len(data):
        op = data[i]
        if op == 'insert':
            rs.insert(int(data[i + 1])); i += 2
        elif op == 'remove':
            rs.remove(int(data[i + 1])); i += 2
        else:
            print(rs.getRandom()); i += 1
        q -= 1

import sys
import random

class RandomizedSetOpt:
    def __init__(self):
        self.pos = {}
        self.arr = []
    def insert(self, val):
        if val in self.pos:
            return False
        self.pos[val] = len(self.arr)
        self.arr.append(val)
        return True
    def remove(self, val):
        if val not in self.pos:
            return False
        i = self.pos[val]
        last = self.arr[-1]
        self.arr[i] = last
        self.pos[last] = i
        self.arr.pop()
        del self.pos[val]
        return True
    def getRandom(self):
        return random.choice(self.arr)

