import sys
import random

class RandomizedSetBest:
    def __init__(self):
        self.idx = {}
        self.arr = []
    def insert(self, val):
        if val in self.idx:
            return False
        self.idx[val] = len(self.arr)
        self.arr.append(val)
        return True
    def remove(self, val):
        if val not in self.idx:
            return False
        i = self.idx.pop(val)
        if i != len(self.arr) - 1:
            moved = self.arr[-1]
            self.arr[i] = moved
            self.idx[moved] = i
        self.arr.pop()
        return True
    def getRandom(self):
        return random.choice(self.arr)

